messages.content:
Game edukasi Endless Runner tentang perangkat input/output komputer dengan tema Neon dan kesulitan Normal. Asumsi penting: monitor tetap masuk kategori Output sesuai definisi baku, dan item layar sentuh tidak dimasukkan agar tidak ambigu.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "input-output-run", title: "Input vs Output Run", seed: "input-output-01",
  theme: { preset: "neon" },

  learning: {
    subject: "Teknologi Informasi",
    concept: "Perbedaan perangkat input dan output komputer",
    objectives: ["Mengelompokkan perangkat komputer berdasarkan fungsinya"],
    misconceptions: ["Monitor dianggap perangkat input karena bisa disentuh (layar sentuh)"],
    mode: "category",
    categories: [
      { id: "input",  label: "Input",  color: "#00E5FF" },
      { id: "output", label: "Output", color: "#FF3DF0" }
    ],
    items: [
      { id: "keyboard",  label: "Keyboard",  category: "input",  explain: "Mengetik huruf dan angka sebagai masukan ke komputer." },
      { id: "mouse",     label: "Mouse",     category: "input",  explain: "Menggerakkan kursor dan mengklik sebagai masukan." },
      { id: "scanner",   label: "Scanner",   category: "input",  explain: "Memindai dokumen menjadi data digital masukan." },
      { id: "mikrofon",  label: "Mikrofon",  category: "input",  explain: "Menangkap suara sebagai masukan ke komputer." },
      { id: "monitor",   label: "Monitor",   category: "output", explain: "Menampilkan gambar dan teks hasil olahan komputer." },
      { id: "printer",   label: "Printer",   category: "output", explain: "Mencetak dokumen ke kertas sebagai hasil keluaran." },
      { id: "speaker",   label: "Speaker",   category: "output", explain: "Mengeluarkan suara hasil olahan komputer." },
      { id: "proyektor", label: "Proyektor", category: "output", explain: "Menampilkan gambar ke layar besar sebagai hasil." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "kabel",   w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "kipas",   w: 60, h: 40, weight: 2 },
      { type: "hazard", id: "kertas",  w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```
